// --- CONFIGURAZIONE ---
u_min := 0;
u_max := 3.14159; // PI: i 3 petali percorsi UNA volta (con 2*PI la curva si
                  // ripassa due volta e i rami diventano tangenti)
v_min := 0;
v_max := 6.28318;
steps := 350;

// --- CODICE SHADER ---
// NB: non dichiarare variabili chiamate PI, pi, tau: il traduttore
// le sostituisce col valore numerico in tutto lo script.

// Parametri Geometrici
float a = 3.0;  // Ampiezza del trifoglio
float r = 0.2;  // Raggio del tubo (0.2 < raggio di curvatura min 0.3:
                // il singolo petalo non si auto-interseca)

// Curva: rosa polare a 3 petali rho = a*cos(3*theta) nel piano z=0,
// con u in [0, PI]. Passa TRE volte per l'origine (u = PI/6, PI/2,
// 5*PI/6): i tre petali si incrociano al centro. A differenza del
// quadrifoglio, qui gli incroci sono TRASVERSALI (le tre tangenti in
// origine sono a 30, 90, 150 gradi, tutte diverse), non tangenti:
// il taglio del cutout e' quindi netto e ben definito.
float c3u = cos(3.0 * u);
float s3u = sin(3.0 * u);
vec3 Curve = vec3(a * c3u * cos(u), a * c3u * sin(u), 0.0);

// --- DERIVATA PRIMA (Velocita' Analitica) ---
vec3 dC = vec3(
    a * (-3.0 * s3u * cos(u) - c3u * sin(u)),
    a * (-3.0 * s3u * sin(u) + c3u * cos(u)),
    0.0
);

vec3 Tangent = normalize(dC);

// --- CALCOLO FRAME STABILE ---
// La curva sta nel piano z=0: la tangente non risulta mai parallela
// a Z, quindi il frame non degenera mai.
vec3 Up = vec3(0.0, 0.0, 1.0);
vec3 Binorm = normalize(cross(Tangent, Up));
vec3 Norm = normalize(cross(Binorm, Tangent));

// --- COSTRUZIONE TUBO ---
vec3 pos = Curve + r * (cos(v) * Norm + sin(v) * Binorm);

// Ritorno del punto in 4D (X, Y, Z, P)
return vec4(pos * 0.35, 0.0);

//CUTOUT_BEGIN
// Taglio delle pareti interne nella zona dell'incrocio (origine).
// Schema del Tubo Autointersecante (distanza PRECISA: scan grossolano
// + 5 passi di Newton, gli step grezzi stimano il minimo con errore
// ~1e-2 e lasciano toppe di z-fight lungo la cucitura).
// I nodi qui sono TRE (u_k = PI/6 + k*PI/3): per un frammento vicino
// al nodo k si controllano i rami degli altri DUE nodi. Il proprio
// ramo non puo' toccarsi (verificato: resta a distanza >= 0.48 con
// r = 0.2), quindi si salta.
float a2 = 3.0;
float r2 = 0.2;
float PI_2 = 3.14159265359;
float NODE0 = PI_2 / 6.0;      // 0.5236
float NSTEP = PI_2 / 3.0;      // 1.0472

// nodo piu' vicino al frammento
float kNear = floor((u - NODE0) / NSTEP + 0.5);
float uNode = NODE0 + kNear * NSTEP;

float activateWindow = 0.5;
bool didCut = false;

if (abs(u - uNode) < activateWindow) {
    float c3f = cos(3.0 * u);
    float s3f = sin(3.0 * u);
    vec3 Curve2 = vec3(a2 * c3f * cos(u), a2 * c3f * sin(u), 0.0);
    vec3 dC2 = vec3(
        a2 * (-3.0 * s3f * cos(u) - c3f * sin(u)),
        a2 * (-3.0 * s3f * sin(u) + c3f * cos(u)),
        0.0
    );
    vec3 Tangent2 = normalize(dC2);
    vec3 Up2 = vec3(0.0, 0.0, 1.0);
    vec3 Binorm2 = normalize(cross(Tangent2, Up2));
    vec3 Norm2 = normalize(cross(Binorm2, Tangent2));
    vec3 pos2 = Curve2 + r2 * (cos(v) * Norm2 + sin(v) * Binorm2);

    float bestDist = 1000.0;

    for (float j = 0.0; j < 3.0; j = j + 1.0) {
        float node = NODE0 + j * NSTEP;
        // salta il nodo del frammento
        if (abs(node - uNode) < 0.1) { continue; }

        // 1. scansione grossolana attorno al nodo
        float bestU = node;
        float bestD = 1000.0;
        for (float k = 0.0; k < 16.0; k = k + 1.0) {
            float u2 = node - 0.4 + 0.8 * (k / 15.0);
            float cc = cos(3.0 * u2);
            vec3 c2 = vec3(a2 * cc * cos(u2), a2 * cc * sin(u2), 0.0);
            float d = length(pos2 - c2);
            if (d < bestD) { bestD = d; bestU = u2; }
        }

        // 2. Newton su g(u2) = dot(pos2 - C(u2), C'(u2)) = 0
        float uN = bestU;
        for (float it = 0.0; it < 5.0; it = it + 1.0) {
            float cN3 = cos(3.0 * uN);
            float sN3 = sin(3.0 * uN);
            float cN1 = cos(uN);
            float sN1 = sin(uN);
            vec3 cN = vec3(a2 * cN3 * cN1, a2 * cN3 * sN1, 0.0);
            vec3 t1 = vec3(a2 * (-3.0 * sN3 * cN1 - cN3 * sN1),
                           a2 * (-3.0 * sN3 * sN1 + cN3 * cN1), 0.0);
            vec3 t2 = vec3(a2 * (-9.0 * cN3 * cN1 + 6.0 * sN3 * sN1 - cN3 * cN1),
                           a2 * (-9.0 * cN3 * sN1 - 6.0 * sN3 * cN1 - cN3 * sN1), 0.0);
            vec3 w = pos2 - cN;
            float g = dot(w, t1);
            float gp = dot(w, t2) - dot(t1, t1);
            if (abs(gp) > 0.000001) { uN = uN - g / gp; }
            uN = clamp(uN, node - 0.45, node + 0.45);
        }
        float cB3 = cos(3.0 * uN);
        vec3 cB = vec3(a2 * cB3 * cos(uN), a2 * cB3 * sin(uN), 0.0);
        bestDist = min(bestDist, min(bestD, length(pos2 - cB)));
    }

    didCut = (bestDist < r2);
}

return didCut;
//CUTOUT_END

